	inline int32_t scalar_i32(uint32_t col = 0, uint32_t row = 0) const { return m.c[col].r[row].i32; }
	inline double scalar_f64(uint32_t col = 0, uint32_t row = 0) const { return m.c[col].r[row].f64; }
	inline int64_t scalar_i64(uint32_t col = 0, uint32_t row = 0) const { return m.c[col].r[row].i64; }
	inline uint64_t scalar_u64(uint32_t col = 0, uint32_t row = 0) const { return m.c[col].r[row].u64; }
	inline const ConstantVector &vector() const { return m.c[0]; }
	inline uint32_t vector_size() const { return m.c[0].vecsize; }
	inline uint32_t columns() const { return m.columns; }
	inline void make_null(const SPIRType &constant_type_) { m = {}; m.columns = constant_type_.columns; for (auto &c : m.c) c.vecsize = constant_type_.vecsize; }
	inline bool constant_is_null() const { if (specialization) return false; if (!subconstants.empty()) return false; for (uint32_t col = 0; col < columns(); col++) for (uint32_t row = 0; row < vector_size(); row++) if (scalar_u64(col, row) != 0) return false; return true; }
	explicit SPIRConstant(uint32_t constant_type_) : constant_type(constant_type_) {}
	SPIRConstant() = default;
	SPIRConstant(TypeID constant_type_, const uint32_t *elements, uint32_t num_elements, bool specialized, bool replicated_ = false)
	    : constant_type(constant_type_) , specialization(specialized) , replicated(replicated_)
	{
		subconstants.reserve(num_elements);
		for (uint32_t i = 0; i < num_elements; i++)
			subconstants.push_back(elements[i]);
		specialization = specialized;
	}
	SPIRConstant(TypeID constant_type_, uint32_t v0, bool specialized)
	    : constant_type(constant_type_) , specialization(specialized) { m.c[0].r[0].u32 = v0; m.c[0].vecsize = 1; m.columns = 1; }
	SPIRConstant(TypeID constant_type_, uint64_t v0, bool specialized)
	    : constant_type(constant_type_) , specialization(specialized) { m.c[0].r[0].u64 = v0; m.c[0].vecsize = 1; m.columns = 1; }
	SPIRConstant(TypeID constant_type_, const SPIRConstant *const *vector_elements, uint32_t num_elements, bool specialized)
	    : constant_type(constant_type_) , specialization(specialized)
	{
		bool matrix = vector_elements[0]->m.c[0].vecsize > 1;
		if (matrix)
		{
			m.columns = num_elements;
			for (uint32_t i = 0; i < num_elements; i++)
			{
				m.c[i] = vector_elements[i]->m.c[0];
				if (vector_elements[i]->specialization)
					m.id[i] = vector_elements[i]->self;
			}
		}
		else
		{
			m.c[0].vecsize = num_elements;
			m.columns = 1;
			for (uint32_t i = 0; i < num_elements; i++)
			{
				m.c[0].r[i] = vector_elements[i]->m.c[0].r[0];
				if (vector_elements[i]->specialization)
					m.c[0].id[i] = vector_elements[i]->self;
			}
		}
	}

	TypeID constant_type = 0;
	ConstantMatrix m;
	bool specialization = false;
	bool is_used_as_array_length = false;
	bool is_used_as_lut = false;
	bool is_null_array_specialized_length = false;
	SmallVector<ConstantID> subconstants;
	bool replicated = false;
	std::string specialization_constant_macro_name;

	SPIRV_CROSS_DECLARE_CLONE(SPIRConstant)
};

struct ObjectPoolGroup
{
	std::unique_ptr<ObjectPoolBase> pools[TypeCount];
};

class Variant
{
public:
	explicit Variant(ObjectPoolGroup *group_)
	    : group(group_)
	{
	}
	~Variant()
	{
		if (holder)
			group->pools[type]->deallocate_opaque(holder);
	}
	Variant(Variant &&other) SPIRV_CROSS_NOEXCEPT { *this = std::move(other); }
	Variant(const Variant &variant) = delete;
	Variant &operator=(Variant &&other) SPIRV_CROSS_NOEXCEPT { if (this != &other) { if (holder) group->pools[type]->deallocate_opaque(holder); holder = other.holder; group = other.group; type = other.type; allow_type_rewrite = other.allow_type_rewrite; other.holder = nullptr; other.type = TypeNone; } return *this; }
	Variant &operator=(const Variant &other)
	{
#ifdef SPIRV_CROSS_COPY_CONSTRUCTOR_SANITIZE
		abort();
#endif
		if (this != &other)
		{
			if (holder)
				group->pools[type]->deallocate_opaque(holder);
			if (other.holder)
				holder = other.holder->clone(group->pools[other.type].get());
			else
				holder = nullptr;
			type = other.type;
			allow_type_rewrite = other.allow_type_rewrite;
		}
		return *this;
	}
	void set(IVariant *val, Types new_type)
	{
		if (holder)
			group->pools[type]->deallocate_opaque(holder);
		holder = nullptr;
		if (!allow_type_rewrite && type != TypeNone && type != new_type)
		{
			if (val)
				group->pools[new_type]->deallocate_opaque(val);
			SPIRV_CROSS_THROW("Overwriting a variant with new type.");
		}
		holder = val; type = new_type; allow_type_rewrite = false;
	}
	template <typename T, typename... Ts>
	T *allocate_and_set(Types new_type, Ts &&... ts)
	{
		T *val = static_cast<ObjectPool<T> &>(*group->pools[new_type]).allocate(std::forward<Ts>(ts)...);
		set(val, new_type);
		return val;
	}
	template <typename T> T &get() { if (!holder) SPIRV_CROSS_THROW("nullptr"); if (static_cast<Types>(T::type) != type) SPIRV_CROSS_THROW("Bad cast"); return *static_cast<T *>(holder); }
	template <typename T> const T &get() const { if (!holder) SPIRV_CROSS_THROW("nullptr"); if (static_cast<Types>(T::type) != type) SPIRV_CROSS_THROW("Bad cast"); return *static_cast<const T *>(holder); }
	Types get_type() const { return type; }
	ID get_id() const { return holder ? holder->self : ID(0); }
	bool empty() const { return !holder; }
	void reset() { if (holder) group->pools[type]->deallocate_opaque(holder); holder = nullptr; type = TypeNone; }
	void set_allow_type_rewrite() { allow_type_rewrite = true; }
private:
	ObjectPoolGroup *group = nullptr;
	IVariant *holder = nullptr;
	Types type = TypeNone;
	bool allow_type_rewrite = false;
};

