struct SetBindingPair
{
	uint32_t desc_set;
	uint32_t binding;
	inline bool operator==(const SetBindingPair &other) const { return desc_set == other.desc_set && binding == other.binding; }
	inline bool operator<(const SetBindingPair &other) const { return desc_set < other.desc_set || (desc_set == other.desc_set && binding < other.binding); }
};

struct LocationComponentPair
{
	uint32_t location;
	uint32_t component;
	inline bool operator==(const LocationComponentPair &other) const { return location == other.location && component == other.component; }
	inline bool operator<(const LocationComponentPair &other) const { return location < other.location || (location == other.location && component < other.component); }
};

struct StageSetBinding
{
	spv::ExecutionModel model;
	uint32_t desc_set;
	uint32_t binding;
	inline bool operator==(const StageSetBinding &other) const { return model == other.model && desc_set == other.desc_set && binding == other.binding; }
};

struct InternalHasher
{
	inline size_t operator()(const SetBindingPair &value) const
	{
		auto hash_set = std::hash<uint32_t>()(value.desc_set);
		auto hash_binding = std::hash<uint32_t>()(value.binding);
		return (hash_set * 0x10001b31) ^ hash_binding;
	}
	inline size_t operator()(const LocationComponentPair &value) const
	{
		auto hash_set = std::hash<uint32_t>()(value.location);
		auto hash_binding = std::hash<uint32_t>()(value.component);
		return (hash_set * 0x10001b31) ^ hash_binding;
	}
	inline size_t operator()(const StageSetBinding &value) const
	{
		auto hash_model = std::hash<uint32_t>()(value.model);
		auto hash_set = std::hash<uint32_t>()(value.desc_set);
		auto tmp_hash = (hash_model * 0x10001b31) ^ hash_set;
		return (tmp_hash * 0x10001b31) ^ value.binding;
	}
};

