// No allocation or failure; nothing to validate beyond successful call.

// Fetch static, library-owned version string. Must not be freed by caller.
const char *s = spvc_get_commit_revision_and_timestamp();
// Best-effort sanity: do not assert on content; just touch it to exercise path.
if (s && s[0] == '\0') {
    // Empty string is allowed; continue.
}

// Initialize deprecated MSL vertex attribute struct to defaults.
spvc_msl_vertex_attribute attr;
spvc_msl_vertex_attribute_init(&attr);
