spvc_msl_shader_input_init(&input);

// Initialize current MSL shader interface descriptor with rate field.
spvc_msl_shader_interface_var_2 v2;
spvc_msl_shader_interface_var_init_2(&v2);

// Initialize deprecated MSL resource binding mapping to non-zero defaults.
spvc_msl_resource_binding b;
spvc_msl_resource_binding_init(&b);

// Initialize current MSL resource binding mapping with array-count support.
spvc_msl_resource_binding_2 b2;
spvc_msl_resource_binding_init_2(&b2);

// Query an obsolete/aux buffer struct version value.
unsigned v = spvc_msl_get_aux_buffer_struct_version();
(void)v;

// Initialize Metal constexpr sampler config to sensible non-zero defaults.
spvc_msl_constexpr_sampler sampler;
spvc_msl_constexpr_sampler_init(&sampler);

// Initialize Metal Y'CbCr conversion parameters to defaults.
spvc_msl_sampler_ycbcr_conversion conv;
spvc_msl_sampler_ycbcr_conversion_init(&conv);

// Initialize HLSL resource binding remap struct to non-zero defaults.
spvc_hlsl_resource_binding h;
spvc_hlsl_resource_binding_init(&h);

// Destroy the context and all allocations owned by it. The input is a wrapper; pass the real handle via *context.
if (!context || !*context) { FUZZ_BAIL(); }
spvc_context_destroy(*context);
// Do not free the wrapper here; dropping the object from outputs relinquishes it to the fuzzer runtime.

// Release all context-owned allocations while keeping the context itself alive.
if (!context || !*context) { FUZZ_BAIL(); }
spvc_context_release_allocations(*context);
// Bump generation counter to mark that previously returned pointers/arrays are invalidated.
int gen = FUZZ_GET_ATTR_INT(context, "gen");
FUZZ_SET_ATTR_INT(context, "gen", gen + 1);
// Return the same context wrapper as a persistent output.

